// CSD_RATIONALE_BEGIN
// Root-cause of attempt-2 failure (4.1% accuracy):
// 1. `minSpanTokens=3` + immediate close when `IsCompletePrefix` was PREVENTING
//    expression extension. After `n1 * frac` (3 tokens, complete), we forced `>>`
//    before the model could add `+ n2`. The evaluator then extracted `n2` (wrong).
// 2. `UnconstrainedStep` one-at-a-time detection missed combined tokens like
//    `<<price` where `RenderedEndsWith` returns false, leaving spans unconstrained.
// 3. 6 unterminated spans from budget exhaustion inside active spans.
//
// Fix design:
// a) `UnconstrainedChunk` replaces `UnconstrainedStep` for free generation — it
//    reports `stoppedOnOpenSpan` using rendered-text matching, catching `<<word`.
// b) `ConfidenceGatedStep` replaces `AdaptiveConstrainedStep` inside spans —
//    passes model's natural choice through when already parser-valid, intervenes
//    only on grammar violations. This lets the model extend `n1 * frac` with
//    `+ n2` without forced interruption.
// c) Remove `minSpanTokens` gate. Span closes only when model returns EOS
//    (natural stop signal) or budget forces `CloseSpanWithinBudget`.
// d) EOS inside a complete span → `CloseConstrainedSpan`; EOS inside incomplete
//    → break, post-loop recovery with `CloseSpanWithinBudget`.
// e) `closeReserve = 30` — when ≤ 30 steps remain with open span, force-close
//    via `CloseSpanWithinBudget` so final span is always terminated.
// f) Guidance emphasizes: write complete multi-operator expressions, never bare
//    variables; final span must combine ALL relevant variables.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// parser_validity (`insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`):
//
// UnconstrainedChunk branch (outside span): implication vacuous while !inside.
//   After stoppedOnOpen, `EnterObservedConstrainedSpan` sets currentConstrainedOut
//   := [] and parser.IsValidPrefix([]) holds by method precondition, establishing
//   the invariant for the next iteration.
//
// ConfidenceGatedStep branch (inside span): by its postcondition, the returned
//   token is either eosToken or satisfies parser.IsValidPrefix(currentConstrainedOut
//   + [next]). When EOS: if IsCompletePrefix holds, CloseConstrainedSpan exits
//   constrained mode (making implication vacuously true). If not complete, we
//   break; the post-loop uses CloseSpanWithinBudget whose contract guarantees
//   `insideOut ==> parser.IsValidPrefix(currentOut)`. AppendConstrainedToken
//   extends currentConstrainedOut by exactly one valid token, preserving the
//   invariant.
//
// Force-close branch: CloseSpanWithinBudget guarantees
//   `insideOut ==> parser.IsValidPrefix(currentOut)` by its postcondition.
//
// progress (`|generated| <= |generatedPrefix| + steps`):
//
// UnconstrainedChunk: postcondition `|generatedOut| <= |generated_old| + stepsUsed`,
//   steps increases by stepsUsed, so bound is preserved. EnterObservedConstrainedSpan
//   adds 0 tokens at 0 cost.
//
// ConfidenceGatedStep: costs 1 step (steps += 1); AppendConstrainedToken appends
//   at most 1 visible token; CloseConstrainedSpan costs 1 step and appends at most
//   1 `>>` token — each increments both steps and |generated| by 1, preserving the
//   bound linearly.
//
// CloseSpanWithinBudget with budget B: `|generatedOut| <= |generated| + B` and
//   `steps += B`, so bound preserved. Force-close sets steps := maxSteps and
//   breaks, keeping `steps <= maxSteps`.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Solve this grade-school math word problem step by step. Use the exact variable names from the problem. You may write intermediate symbolic values in << >> as you reason (e.g., <<n1 * price>>). For your FINAL answer you MUST write: 'The final answer is <<COMPLETE_EXPRESSION>>' where COMPLETE_EXPRESSION is ONE arithmetic formula combining ALL necessary variables — for example <<int(n1 * frac) + n2>> or <<(n + n * mult) * 7>>. NEVER write a single bare variable as the final answer. Use only: +, -, *, /, //, %, int(), ().");

var steps: nat := 0;
var closeReserve: nat := 30;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  // Reserve budget to close an active span before exhausting steps
  if insideConstrainedOut && steps + closeReserve >= maxSteps {
    var closeBudget := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  }

  if !insideConstrainedOut {
    var actualChunk: nat := 8;
    if steps + actualChunk > maxSteps { actualChunk := maxSteps - steps; }
    var generatedOut, stoppedOnOpen, stoppedOnEos, stepsUsed :=
      helpers.UnconstrainedChunk(lm, prompt, generated, actualChunk, "<<", eosToken);
    generated := generatedOut;
    steps := steps + stepsUsed;
    if stoppedOnOpen {
      var g, inside, current := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := g;
      insideConstrainedOut := inside;
      currentConstrainedOut := current;
    } else if stoppedOnEos {
      break;
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next, wasConst := helpers.ConfidenceGatedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      // Model signals stop; close span if expression is complete
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(
          lm, parser, generated, currentConstrainedOut
        );
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Post-loop recovery: close any still-open span with remaining budget
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var closeBudget := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

